  $insert = @'

persistent_instructions = """
Read ~/.claude/AGENTS.md Engineering Assistant Charter first.
Task start: restate goal, constraints, acceptance in 1-3 sentences.
Fuzzy requests: requirement-clarifier Mini-Spec before apply_patch unless user says 直接执行.
Done = Completed / Verified / Remaining Risks; update task-history and SESSION if present.
High reasoning only for architecture or hard debug; default medium.
"""

'@
  $content = $content -replace '(disable_response_storage = true\r?\n)', "`$1$insert"
