$keep = @('figma@openai-curated', 'build-web-apps@openai-curated')
$lines = Get-Content $configPath
$out = New-Object System.Collections.Generic.List[string]
$i = 0
while ($i -lt $lines.Count) {
  $line = $lines[$i]
  if ($line -match '^\[plugins\."([^"]+@openai-curated)"\]$') {
    $name = $Matches[1]
    $out.Add($line)
    $i++
    if ($i -lt $lines.Count -and $lines[$i] -match '^enabled = ') {
      if ($keep -contains $name) { $out.Add($lines[$i]) } else { $out.Add('enabled = false') }
      $i++
    }
    continue
  }
  $out.Add($line)
  $i++
}
# Apply reasoning + persistent to out list from $content for first part
$header = ($content -split '(?=\[features\])')[0]
$rest = ($content -split '(?=\[features\])', 2)[1]
if ($rest) {
  $bodyLines = ($header.TrimEnd() + "`n" + '[features]' + $rest) -split "`r?`n"
} else {
  $bodyLines = $header -split "`r?`n"
}
# Rebuild: use line processor on original but fix header from $content first lines
$final = New-Object System.Collections.Generic.List[string]
$inCurated = $false
$curName = ''
Get-Content $configPath | ForEach-Object {
  $l = $_
  if ($l -match '^\[plugins\."([^"]+@openai-curated)"\]$') {
    $curName = $Matches[1]
    $inCurated = $true
    $final.Add($l)
